import{_ as d,C as p,o as a,c,a0 as n,b as o,w as t,a as s,E as r,a1 as l}from"./chunks/framework.CzVS_xMp.js";const g="data:image/svg+xml;base64,",h="/ai-data-center-systems/assets/kv-cache-decoding.CUcJYn92.svg",C=JSON.parse('{"title":"Lecture 3: Large Language Models, Decoding, Prompting, and Inference","description":"","frontmatter":{},"headers":[],"relativePath":"courses/cme295/lec-03/index.md","filePath":"courses/cme295/lec-03/index.md","lastUpdated":1788490169000}'),m={name:"courses/cme295/lec-03/index.md"};function u(b,e,k,x,y,I){const i=p("Mermaid");return a(),c("div",null,[e[4]||(e[4]=n('<h1 id="lecture-3-large-language-models-decoding-prompting-and-inference" tabindex="-1">Lecture 3: Large Language Models, Decoding, Prompting, and Inference <a class="header-anchor" href="#lecture-3-large-language-models-decoding-prompting-and-inference" aria-label="Permalink to &quot;Lecture 3: Large Language Models, Decoding, Prompting, and Inference&quot;">​</a></h1><p>Source: <a href="https://www.youtube.com/watch?v=Q5baLehv5So" target="_blank" rel="noreferrer">CME295 Lecture 3</a></p><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#goal">Goal</a></li><li><a href="#lecture-overview">Lecture Overview</a></li><li><a href="#from-transformer-families-to-llms">From Transformer Families to LLMs</a></li><li><a href="#what-makes-a-language-model-large">What Makes a Language Model Large</a></li><li><a href="#decoder-only-backbone">Decoder-Only Backbone</a></li><li><a href="#mixture-of-experts">Mixture of Experts</a></li><li><a href="#sparse-moe-and-routing">Sparse MoE and Routing</a></li><li><a href="#routing-collapse-and-load-balancing">Routing Collapse and Load Balancing</a></li><li><a href="#next-token-generation">Next Token Generation</a></li><li><a href="#greedy-decoding-and-beam-search">Greedy Decoding and Beam Search</a></li><li><a href="#sampling-top-k-top-p-and-temperature">Sampling, Top-K, Top-P, and Temperature</a></li><li><a href="#guided-decoding">Guided Decoding</a></li><li><a href="#context-length-and-context-rot">Context Length and Context Rot</a></li><li><a href="#prompt-structure">Prompt Structure</a></li><li><a href="#in-context-learning">In-Context Learning</a></li><li><a href="#chain-of-thought-and-self-consistency">Chain of Thought and Self-Consistency</a></li><li><a href="#inference-efficiency">Inference Efficiency</a></li><li><a href="#kv-cache">KV Cache</a></li><li><a href="#pagedattention">PagedAttention</a></li><li><a href="#multi-latent-attention">Multi-Latent Attention</a></li><li><a href="#speculative-decoding">Speculative Decoding</a></li><li><a href="#multi-token-prediction">Multi-Token Prediction</a></li><li><a href="#practical-tips-and-notes">Practical Tips and Notes</a></li><li><a href="#lecture-summary">Lecture Summary</a></li><li><a href="#key-terms">Key Terms</a></li><li><a href="#questions">Questions</a></li><li><a href="#answers">Answers</a></li></ul><hr><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>이번 강의의 목표는 현대 LLM을 <strong>decoder-only Transformer 기반의 next-token prediction system</strong>으로 이해하고, 그 위에서 실제 응답이 어떻게 생성되고 최적화되는지 파악하는 것이다.</p><p>핵심 메시지는 다음과 같다.</p><blockquote><p>LLM은 단순히 큰 Transformer가 아니라, decoder-only architecture, token sampling strategy, prompt design, KV cache, MoE, speculative decoding 같은 학습/추론/서빙 기법이 결합된 시스템이다.</p></blockquote><p>이 강의는 다음을 다룬다.</p><ul><li>LLM의 정의와 decoder-only model의 위치</li><li>model size, training tokens, compute 관점의 &quot;large&quot;</li><li>Mixture of Experts, sparse MoE, router, routing collapse</li><li>greedy decoding, beam search, sampling</li><li>top-K, top-P, temperature의 의미</li><li>guided decoding과 structured output</li><li>context length, context rot, needle-in-a-haystack 문제</li><li>prompt 구성요소와 in-context learning</li><li>zero-shot, few-shot, chain-of-thought, self-consistency</li><li>KV cache, GQA, PagedAttention, multi-latent attention</li><li>speculative decoding과 multi-token prediction</li></ul><hr><h2 id="lecture-overview" tabindex="-1">Lecture Overview <a class="header-anchor" href="#lecture-overview" aria-label="Permalink to &quot;Lecture Overview&quot;">​</a></h2><p>Lecture 1과 2에서는 self-attention, Transformer, encoder-decoder, encoder-only, decoder-only model family를 다뤘다. Lecture 3는 이 기반 위에서 드디어 Large Language Model, LLM을 정의한다.</p><p>강의의 전반부는 LLM의 구조와 응답 생성 방식이다. LLM은 대부분 decoder-only Transformer이며, 다음 token probability distribution을 만든다. 이 distribution에서 실제 token을 고르는 방식에 따라 deterministic output, diverse output, structured output이 달라진다.</p><p>중반부는 prompting이다. Context length, prompt 구성, zero-shot/few-shot, chain-of-thought, self-consistency를 통해 model weight를 바꾸지 않고도 model behavior를 조정하는 방법을 다룬다.</p><p>후반부는 inference efficiency다. Autoregressive generation은 token을 하나씩 생성하므로 중복 계산과 memory pressure가 크다. 이를 줄이기 위해 KV cache, GQA, PagedAttention, multi-latent attention, speculative decoding, multi-token prediction 같은 기법을 사용한다.</p><hr><h2 id="from-transformer-families-to-llms" tabindex="-1">From Transformer Families to LLMs <a class="header-anchor" href="#from-transformer-families-to-llms" aria-label="Permalink to &quot;From Transformer Families to LLMs&quot;">​</a></h2><p>이전 강의에서 Transformer 계열 model은 세 가지로 정리했다.</p><table tabindex="0"><thead><tr><th>Family</th><th>Structure</th><th>Typical task</th></tr></thead><tbody><tr><td>Encoder-decoder</td><td>encoder + decoder</td><td>translation, text-to-text, T5</td></tr><tr><td>Encoder-only</td><td>encoder only</td><td>classification, retrieval, BERT</td></tr><tr><td>Decoder-only</td><td>decoder only</td><td>generation, GPT-style LLM</td></tr></tbody></table><p>LLM은 현재 통상적으로 <strong>large decoder-only text-to-text language model</strong>을 뜻한다. 과거에는 BERT 같은 encoder-only model도 큰 language model로 부르는 경우가 있었지만, 강의에서는 현대적 의미의 LLM을 text를 생성하는 decoder-only model로 제한한다.</p><p>BERT는 문장이나 문서를 좋은 embedding으로 encode하는 데 강하지만, 자체적으로 autoregressive text generation을 수행하지 않는다. 따라서 이 강의의 정의에서는 LLM으로 보지 않는다.</p><hr><h2 id="what-makes-a-language-model-large" tabindex="-1">What Makes a Language Model Large <a class="header-anchor" href="#what-makes-a-language-model-large" aria-label="Permalink to &quot;What Makes a Language Model Large&quot;">​</a></h2><p>Language model은 token sequence에 probability를 부여하는 model이다. Decoder-only LLM은 다음 token의 conditional probability를 반복적으로 계산한다.</p><div class="language-math vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">math</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P(x_1, x_2, ..., x_T) = \\prod_{t=1}^{T} P(x_t | x_{\\lt t})</span></span></code></pre></div><p>LLM이 &quot;large&quot;하다는 말은 보통 세 가지 차원을 포함한다.</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Meaning</th><th>Typical scale</th></tr></thead><tbody><tr><td>Model size</td><td>parameter 수</td><td>billions to hundreds of billions</td></tr><tr><td>Training data</td><td>pre-training token 수</td><td>hundreds of billions to trillions</td></tr><tr><td>Compute</td><td>training/inference GPU 연산량</td><td>many GPUs, large FLOPs</td></tr></tbody></table><p>강의에서는 LLM을 말할 때 적어도 billion-scale parameter를 떠올리면 된다고 설명한다. 최신 model은 수백 billion parameter, 수 trillion token 이상의 data, 대규모 GPU cluster를 필요로 한다.</p><hr><h2 id="decoder-only-backbone" tabindex="-1">Decoder-Only Backbone <a class="header-anchor" href="#decoder-only-backbone" aria-label="Permalink to &quot;Decoder-Only Backbone&quot;">​</a></h2><p>LLM의 backbone은 decoder-only Transformer다. 원래 Transformer decoder에는 masked self-attention, cross-attention, FFN이 있었지만, decoder-only model에서는 encoder가 없으므로 cross-attention이 사라진다.</p>',33)),(a(),o(l,null,{default:t(()=>[r(i,{id:"mermaid-371",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20A%5BInput%20tokens%5D%20--%3E%20B%5BToken%20embeddings%5D%0A%20%20%20%20B%20--%3E%20C%5BMasked%20self-attention%5D%0A%20%20%20%20C%20--%3E%20D%5BFFN%20or%20MoE%20FFN%5D%0A%20%20%20%20D%20--%3E%20E%5BAdd%20%2F%20Norm%5D%0A%20%20%20%20E%20--%3E%20F%5BLogits%20over%20vocabulary%5D%0A%20%20%20%20F%20--%3E%20G%5BSoftmax%5D%0A%20%20%20%20G%20--%3E%20H%5BNext-token%20distribution%5D%0A%20%20%20%20H%20--%3E%20I%5BDecoding%20strategy%5D%0A%20%20%20%20I%20--%3E%20J%5BNext%20token%5D%0A%20%20%20%20J%20-.%20fed%20back%20.-%3E%20A%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20A%2CJ%20primary%0A%20%20%20%20class%20B%2CC%2CD%2CE%2CF%2CG%2CH%20secondary%0A%20%20%20%20class%20I%20accent%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n(`<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input tokens</span></span>
<span class="line"><span>  -&gt; masked self-attention</span></span>
<span class="line"><span>  -&gt; feed-forward network</span></span>
<span class="line"><span>  -&gt; add / norm</span></span>
<span class="line"><span>  -&gt; next-token logits</span></span></code></pre></div><p>주요 특징은 다음과 같다.</p><ul><li>causal mask를 사용해 미래 token을 보지 않는다.</li><li>이전 token context를 기반으로 다음 token probability를 계산한다.</li><li>generation은 autoregressive하게 반복된다.</li><li>GPT, Llama, Gemma, DeepSeek, Mistral, Qwen 등 대부분의 현대 LLM이 이 계열이다.</li></ul><hr><h2 id="mixture-of-experts" tabindex="-1">Mixture of Experts <a class="header-anchor" href="#mixture-of-experts" aria-label="Permalink to &quot;Mixture of Experts&quot;">​</a></h2><p>LLM은 parameter 수가 크기 때문에 매 forward pass에서 모든 parameter를 사용하는 것이 비효율적일 수 있다. 강의에서는 이를 전문가 metaphor로 설명한다. 수학 질문이 있으면 수학자에게 묻는 것이 자연스럽지, 역사학자와 화학자까지 모두 같은 비중으로 참여할 필요는 없다.</p><p><img src="`+g+`" alt="Sparse MoE routing"></p><p>Mixture of Experts, MoE는 이 생각을 model architecture에 반영한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input x</span></span>
<span class="line"><span>  -&gt; router / gate G(x)</span></span>
<span class="line"><span>  -&gt; selected expert(s)</span></span>
<span class="line"><span>  -&gt; weighted output</span></span></code></pre></div><p>일반적인 MoE 출력은 다음처럼 쓸 수 있다.</p><div class="language-math vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">math</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\\hat{y} = \\sum_i G_i(x) E_i(x)</span></span></code></pre></div><p>여기서 <code>E_i</code>는 expert network, <code>G_i(x)</code>는 gate 또는 router가 expert <code>i</code>에 부여한 weight다.</p><hr><h2 id="sparse-moe-and-routing" tabindex="-1">Sparse MoE and Routing <a class="header-anchor" href="#sparse-moe-and-routing" aria-label="Permalink to &quot;Sparse MoE and Routing&quot;">​</a></h2><p>MoE에는 dense MoE와 sparse MoE가 있다.</p><table tabindex="0"><thead><tr><th>Type</th><th>Expert usage</th><th>Compute implication</th></tr></thead><tbody><tr><td>Dense MoE</td><td>모든 expert output을 사용하되 weight를 다르게 줌</td><td>모든 expert 계산 필요</td></tr><tr><td>Sparse MoE</td><td>top-K expert만 선택</td><td>active compute 감소</td></tr></tbody></table><p>현대 LLM에서 중요한 것은 sparse MoE다. 전체 parameter capacity는 크게 늘리되, 각 token forward pass에서 활성화되는 expert 수는 제한한다. 이렇게 하면 total parameter는 커져도 active parameter와 FLOPs는 상대적으로 통제할 수 있다.</p><p>LLM에서 MoE는 보통 feed-forward network, FFN 위치에 들어간다. FFN은 <code>d_model -&gt; d_ff -&gt; d_model</code> 구조이며, <code>d_ff</code>가 <code>d_model</code>보다 훨씬 큰 경우가 많아 parameter와 연산량이 크다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>decoder block</span></span>
<span class="line"><span>  -&gt; masked self-attention</span></span>
<span class="line"><span>  -&gt; MoE FFN</span></span>
<span class="line"><span>       router chooses top-K experts per token</span></span>
<span class="line"><span>  -&gt; residual / norm</span></span></code></pre></div><p>중요한 점은 routing이 token 단위로 일어난다는 것이다. 같은 sequence 안에서도 token마다 다른 expert를 사용할 수 있고, layer마다 router와 expert 선택이 다를 수 있다.</p><hr><h2 id="routing-collapse-and-load-balancing" tabindex="-1">Routing Collapse and Load Balancing <a class="header-anchor" href="#routing-collapse-and-load-balancing" aria-label="Permalink to &quot;Routing Collapse and Load Balancing&quot;">​</a></h2><p>Sparse MoE에는 routing collapse 문제가 있다. Router가 계속 일부 expert만 선택하면, 다른 expert는 거의 학습되지 않고 compute capacity도 낭비된다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bad routing:</span></span>
<span class="line"><span>all tokens -&gt; expert 1</span></span>
<span class="line"><span>expert 2, 3, 4 -&gt; unused</span></span></code></pre></div><p>이를 완화하기 위해 load balancing loss를 추가한다. 강의에서는 다음 두 quantity를 소개한다.</p><table tabindex="0"><thead><tr><th>Quantity</th><th>Meaning</th></tr></thead><tbody><tr><td><code>f_i</code></td><td>expert <code>i</code>로 routing된 token fraction</td></tr><tr><td><code>P_i</code></td><td>expert <code>i</code>에 대한 average routing probability</td></tr></tbody></table><p>추가 loss는 expert 사용량과 routing probability가 더 uniform해지도록 유도한다. 핵심은 router가 특정 expert에만 collapse하지 않도록 loss function에서 인센티브를 주는 것이다.</p><p>다른 기법으로 noisy gating도 있다. Router score에 noise를 넣어 training 중 다양한 expert가 선택될 가능성을 높인다. Dropout과 비슷하게 exploration을 돕는 역할을 할 수 있다.</p><hr><h2 id="next-token-generation" tabindex="-1">Next Token Generation <a class="header-anchor" href="#next-token-generation" aria-label="Permalink to &quot;Next Token Generation&quot;">​</a></h2><p>LLM은 input token sequence를 받아 다음 token에 대한 probability distribution을 출력한다.</p>`,31)),(a(),o(l,null,{default:t(()=>[r(i,{id:"mermaid-529",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20A%5BContext%20tokens%5D%20--%3E%20B%5BDecoder-only%20LLM%5D%0A%20%20%20%20B%20--%3E%20C%5BLogits%5D%0A%20%20%20%20C%20--%3E%20D%5BTemperature%20scaling%5D%0A%20%20%20%20D%20--%3E%20E%5BSoftmax%20probabilities%5D%0A%20%20%20%20E%20--%3E%20F%7BChoose%20token%7D%0A%20%20%20%20F%20--%3E%20G%5BGreedy%3Cbr%2F%3Eargmax%5D%0A%20%20%20%20F%20--%3E%20H%5BBeam%20search%3Cbr%2F%3Ekeep%20K%20paths%5D%0A%20%20%20%20F%20--%3E%20I%5BSampling%3Cbr%2F%3Etop-K%20%2F%20top-P%5D%0A%20%20%20%20G%20--%3E%20J%5BAppend%20token%5D%0A%20%20%20%20H%20--%3E%20J%0A%20%20%20%20I%20--%3E%20J%0A%20%20%20%20J%20-.%20repeat%20until%20EOS%20.-%3E%20A%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20A%2CB%2CJ%20primary%0A%20%20%20%20class%20C%2CD%2CE%20secondary%0A%20%20%20%20class%20G%2CH%20note%0A%20%20%20%20class%20F%2CI%20accent%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n(`<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>context tokens</span></span>
<span class="line"><span>  -&gt; decoder-only LLM</span></span>
<span class="line"><span>  -&gt; logits over vocabulary</span></span>
<span class="line"><span>  -&gt; softmax</span></span>
<span class="line"><span>  -&gt; probability distribution</span></span>
<span class="line"><span>  -&gt; choose next token</span></span></code></pre></div><p>중요한 질문은 다음이다.</p><blockquote><p>Probability distribution이 주어졌을 때 실제 next token을 어떻게 고를 것인가?</p></blockquote><p>이 선택은 model architecture가 아니라 inference-time decoding strategy다. Transformer 자체는 deterministic하게 logits를 계산한다. 응답이 매번 달라지는 이유는 보통 다음 token sampling 단계가 stochastic하기 때문이다.</p><hr><h2 id="greedy-decoding-and-beam-search" tabindex="-1">Greedy Decoding and Beam Search <a class="header-anchor" href="#greedy-decoding-and-beam-search" aria-label="Permalink to &quot;Greedy Decoding and Beam Search&quot;">​</a></h2><h3 id="greedy-decoding" tabindex="-1">Greedy Decoding <a class="header-anchor" href="#greedy-decoding" aria-label="Permalink to &quot;Greedy Decoding&quot;">​</a></h3><p>가장 단순한 방식은 항상 probability가 가장 높은 token을 고르는 것이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>next token = argmax P(token | context)</span></span></code></pre></div><p>이 방식은 deterministic하고 빠르다. 하지만 두 가지 문제가 있다.</p><ul><li>같은 input에 항상 같은 output이 나온다.</li><li>각 step에서 locally optimal인 token을 고르지만, 전체 sequence probability가 globally optimal이라는 보장은 없다.</li></ul><h3 id="beam-search" tabindex="-1">Beam Search <a class="header-anchor" href="#beam-search" aria-label="Permalink to &quot;Beam Search&quot;">​</a></h3><p>Beam search는 한 path만 유지하지 않고, beam width <code>K</code>개의 유망한 partial sequence를 유지한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BOS</span></span>
<span class="line"><span>  -&gt; keep top K first tokens</span></span>
<span class="line"><span>  -&gt; expand each path</span></span>
<span class="line"><span>  -&gt; keep top K full paths</span></span>
<span class="line"><span>  -&gt; repeat</span></span></code></pre></div><p>Sequence probability는 token probability의 곱이고, log space에서는 log probability의 합으로 계산한다.</p><div class="language-math vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">math</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\\log P(x_{1:T}) = \\sum_{t=1}^{T} \\log P(x_t | x_{\\lt t})</span></span></code></pre></div><p>Beam search는 greedy보다 전체 sequence 관점에 가깝지만, 계산량이 크고 diversity가 낮다. 또한 probability를 계속 곱하면 긴 sequence일수록 score가 작아져 shorter output을 선호하는 문제가 생긴다. 그래서 length penalty 같은 보정이 필요하다.</p><p>강의에서는 beam search가 machine translation처럼 높은 likelihood의 정답형 output이 중요한 task에는 유용하지만, creative response generation에는 보통 sampling이 더 적합하다고 설명한다.</p><hr><h2 id="sampling-top-k-top-p-and-temperature" tabindex="-1">Sampling, Top-K, Top-P, and Temperature <a class="header-anchor" href="#sampling-top-k-top-p-and-temperature" aria-label="Permalink to &quot;Sampling, Top-K, Top-P, and Temperature&quot;">​</a></h2><p>Sampling은 model이 출력한 probability distribution에서 실제 token을 무작위로 뽑는 방식이다. 확률이 높은 token이 더 자주 나오지만, 낮은 확률 token도 선택될 수 있다.</p><h3 id="top-k-sampling" tabindex="-1">Top-K Sampling <a class="header-anchor" href="#top-k-sampling" aria-label="Permalink to &quot;Top-K Sampling&quot;">​</a></h3><p>Top-K sampling은 probability가 가장 높은 <code>K</code>개 token만 남기고 그 안에서 sampling한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vocabulary distribution</span></span>
<span class="line"><span>  -&gt; keep top K tokens</span></span>
<span class="line"><span>  -&gt; renormalize</span></span>
<span class="line"><span>  -&gt; sample</span></span></code></pre></div><p>이렇게 하면 매우 낮은 확률의 이상한 token이 선택될 위험을 줄일 수 있다.</p><h3 id="top-p-sampling" tabindex="-1">Top-P Sampling <a class="header-anchor" href="#top-p-sampling" aria-label="Permalink to &quot;Top-P Sampling&quot;">​</a></h3><p>Top-P, nucleus sampling은 누적 probability가 threshold <code>p</code>를 넘을 때까지 높은 확률 token을 남긴다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sort tokens by probability</span></span>
<span class="line"><span>keep smallest set whose cumulative probability &gt;= p</span></span>
<span class="line"><span>sample from that set</span></span></code></pre></div><p>Top-K는 token 개수를 고정하고, top-P는 probability mass를 고정한다.</p><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>Softmax에는 temperature <code>T</code>를 넣을 수 있다.</p><div class="language-math vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">math</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P_i = \\frac{\\exp(z_i / T)}{\\sum_j \\exp(z_j / T)}</span></span></code></pre></div><p>여기서 <code>z_i</code>는 token <code>i</code>의 logit이다.</p><table tabindex="0"><thead><tr><th>Temperature</th><th>Distribution</th><th>Behavior</th></tr></thead><tbody><tr><td>Low</td><td>spiky</td><td>높은 확률 token에 집중, deterministic에 가까움</td></tr><tr><td>High</td><td>flatter</td><td>낮은 확률 token도 더 자주 선택, creative해짐</td></tr><tr><td>Very high</td><td>near-uniform</td><td>품질 저하 가능</td></tr></tbody></table><p>강의에서 중요한 포인트는 <strong>Transformer 계산 자체는 deterministic</strong>이라는 점이다. 비결정성은 주로 sampling에서 나온다. 단, 실제 hardware에서는 floating-point reduction 순서, GPU kernel nondeterminism 등으로 temperature 0에서도 완벽히 같은 결과가 항상 보장되지 않을 수 있다.</p><hr><h2 id="guided-decoding" tabindex="-1">Guided Decoding <a class="header-anchor" href="#guided-decoding" aria-label="Permalink to &quot;Guided Decoding&quot;">​</a></h2><p>Guided decoding은 output이 특정 format을 따라야 할 때 사용하는 decoding 방식이다. 예를 들어 JSON을 생성해야 한다면, 단순히 prompt에 &quot;JSON으로 답해&quot;라고 쓰고 실패하면 retry하는 방식은 비효율적이다.</p><p>Guided decoding은 generation 중에 문법적으로 invalid한 next token을 제거한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>desired output: JSON</span></span>
<span class="line"><span></span></span>
<span class="line"><span>step 1: only &quot;{&quot; is valid</span></span>
<span class="line"><span>step 2: only valid property name tokens are allowed</span></span>
<span class="line"><span>step 3: only &quot;:&quot; or valid value tokens are allowed</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>구현에는 finite state machine, grammar constraint, parser-based filtering 같은 기법이 사용될 수 있다. 핵심은 probability distribution에서 invalid token을 mask한 뒤 valid token 중에서 decoding strategy를 적용하는 것이다.</p><hr><h2 id="context-length-and-context-rot" tabindex="-1">Context Length and Context Rot <a class="header-anchor" href="#context-length-and-context-rot" aria-label="Permalink to &quot;Context Length and Context Rot&quot;">​</a></h2><p>Context length, context size, window size는 LLM이 한 번에 볼 수 있는 input token 수를 뜻한다. 최신 model은 수만, 수십만, 심지어 million-scale token context를 지원하기도 한다.</p><p>하지만 context length가 길다고 모든 문제가 해결되는 것은 아니다. 강의에서는 <strong>context rot</strong> 현상을 소개한다. 긴 context 안에 정답이 들어 있어도 model이 그 정보를 안정적으로 찾아내지 못하는 현상이다.</p><p>Needle-in-a-haystack test는 긴 문서 안에 answer를 숨겨 두고 model이 찾아낼 수 있는지 평가한다. Context가 길어지고 distractor가 많아질수록 retrieval capability가 떨어질 수 있다.</p><p>운영 관점에서 중요한 결론은 다음이다.</p><blockquote><p>LLM에 모든 자료를 넣는 것보다, 필요한 context를 잘 골라 넣는 것이 더 중요할 수 있다.</p></blockquote><p>RAG나 long-context QA에서는 retrieval quality, chunking, reranking, context ordering이 model context length만큼 중요하다.</p><hr><h2 id="prompt-structure" tabindex="-1">Prompt Structure <a class="header-anchor" href="#prompt-structure" aria-label="Permalink to &quot;Prompt Structure&quot;">​</a></h2><p>Prompt에는 엄격한 이론적 표준은 없지만, 강의에서는 보통 다음 네 요소로 나누어 볼 수 있다고 설명한다.</p>`,52)),(a(),o(l,null,{default:t(()=>[r(i,{id:"mermaid-720",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20TB%0A%20%20%20%20A%5BPrompt%5D%20--%3E%20B%5BContext%3Cbr%2F%3Erole%2C%20setting%2C%20background%5D%0A%20%20%20%20A%20--%3E%20C%5BInstructions%3Cbr%2F%3Etask%20to%20perform%5D%0A%20%20%20%20A%20--%3E%20D%5BInputs%3Cbr%2F%3Edata%20to%20operate%20on%5D%0A%20%20%20%20A%20--%3E%20E%5BConstraints%3Cbr%2F%3Eformat%2C%20safety%2C%20style%5D%0A%20%20%20%20B%20--%3E%20F%5BLLM%20response%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20A%20primary%0A%20%20%20%20class%20B%2CC%2CD%20secondary%0A%20%20%20%20class%20E%20accent%0A%20%20%20%20class%20F%20primary%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=n(`<table tabindex="0"><thead><tr><th>Part</th><th>Role</th></tr></thead><tbody><tr><td>Context</td><td>상황, persona, 배경 정보</td></tr><tr><td>Instructions</td><td>model이 수행해야 할 task</td></tr><tr><td>Inputs</td><td>task에 적용할 실제 data</td></tr><tr><td>Constraints</td><td>output format, safety, length, style 제한</td></tr></tbody></table><p>예를 들어 ChatGPT류 system에서는 사용자가 직접 보지 못하는 hidden instructions나 safety constraints도 prompt context에 포함될 수 있다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Context: You are a helpful assistant.</span></span>
<span class="line"><span>Instruction: Summarize the following text.</span></span>
<span class="line"><span>Input: &lt;document&gt;</span></span>
<span class="line"><span>Constraint: Korean, bullet points, no unsupported claims.</span></span></code></pre></div><p>이 mental model을 사용하면 prompt failure를 더 쉽게 디버깅할 수 있다. Model이 잘못된 output을 낼 때 context가 부족한지, instruction이 모호한지, input이 noisy한지, constraint가 충돌하는지 분리해 볼 수 있다.</p><hr><h2 id="in-context-learning" tabindex="-1">In-Context Learning <a class="header-anchor" href="#in-context-learning" aria-label="Permalink to &quot;In-Context Learning&quot;">​</a></h2><p>In-context learning은 model weight를 업데이트하지 않고 prompt 안의 예시나 설명만으로 model behavior를 조정하는 방법이다. 여기서 &quot;learning&quot;은 parameter learning이 아니라 context 안에서 task pattern을 파악한다는 뜻이다.</p><h3 id="zero-shot" tabindex="-1">Zero-Shot <a class="header-anchor" href="#zero-shot" aria-label="Permalink to &quot;Zero-Shot&quot;">​</a></h3><p>Zero-shot은 예시 없이 instruction과 input만 주는 방식이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Translate this sentence to French:</span></span>
<span class="line"><span>&quot;A cute teddy bear is reading.&quot;</span></span></code></pre></div><h3 id="few-shot" tabindex="-1">Few-Shot <a class="header-anchor" href="#few-shot" aria-label="Permalink to &quot;Few-Shot&quot;">​</a></h3><p>Few-shot은 input-output example을 몇 개 제공한 뒤 새 input을 넣는다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Input: teddy</span></span>
<span class="line"><span>Output: &lt;bedtime story example&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Input: bob</span></span>
<span class="line"><span>Output: &lt;bedtime story example&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Input: luna</span></span>
<span class="line"><span>Output:</span></span></code></pre></div><p>Few-shot은 model을 task format에 잘 맞출 수 있지만, example을 수집해야 하고 context token을 더 많이 사용한다. 또한 example이 너무 좁으면 model이 그 example distribution에 과하게 맞춰져 generalization이 떨어질 수 있다.</p><p>최근 model은 reasoning 능력이 좋아지면서, 좋은 natural language instruction만으로 few-shot보다 낫거나 비슷한 성능을 보이는 경우도 있다. 강의에서는 plan-and-solve류 prompting도 이 흐름의 예로 언급한다.</p><hr><h2 id="chain-of-thought-and-self-consistency" tabindex="-1">Chain of Thought and Self-Consistency <a class="header-anchor" href="#chain-of-thought-and-self-consistency" aria-label="Permalink to &quot;Chain of Thought and Self-Consistency&quot;">​</a></h2><h3 id="chain-of-thought" tabindex="-1">Chain of Thought <a class="header-anchor" href="#chain-of-thought" aria-label="Permalink to &quot;Chain of Thought&quot;">​</a></h3><p>Chain of Thought, CoT는 model이 최종 답만 내지 않고 reasoning path를 먼저 생성하게 하는 prompting 기법이다.</p>`,19)),(a(),o(l,null,{default:t(()=>[r(i,{id:"mermaid-811",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22theme%22%3A%20%22base%22%2C%20%22themeVariables%22%3A%20%7B%22background%22%3A%20%22%23171717%22%2C%20%22primaryColor%22%3A%20%22%23232323%22%2C%20%22primaryTextColor%22%3A%20%22%23f5f5f5%22%2C%20%22primaryBorderColor%22%3A%20%22%23d0d0d0%22%2C%20%22lineColor%22%3A%20%22%23cfcfcf%22%2C%20%22fontFamily%22%3A%20%22Inter%2C%20Arial%2C%20sans-serif%22%7D%7D%7D%25%25%0Aflowchart%20LR%0A%20%20%20%20Q%5BQuestion%5D%20--%3E%20R1%5BReasoning%20sample%201%5D%0A%20%20%20%20Q%20--%3E%20R2%5BReasoning%20sample%202%5D%0A%20%20%20%20Q%20--%3E%20R3%5BReasoning%20sample%203%5D%0A%20%20%20%20R1%20--%3E%20A1%5BFinal%20answer%20A%5D%0A%20%20%20%20R2%20--%3E%20A2%5BFinal%20answer%20B%5D%0A%20%20%20%20R3%20--%3E%20A3%5BFinal%20answer%20A%5D%0A%20%20%20%20A1%20--%3E%20V%5BMajority%20vote%5D%0A%20%20%20%20A2%20--%3E%20V%0A%20%20%20%20A3%20--%3E%20V%0A%20%20%20%20V%20--%3E%20O%5BSelected%20answer%20A%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23232323%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20secondary%20fill%3A%233b2f20%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20note%20fill%3A%2352676b%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20classDef%20accent%20fill%3A%2362164d%2Cstroke%3A%23d0d0d0%2Ccolor%3A%23f5f5f5%2Cstroke-width%3A2px%3B%0A%20%20%20%20class%20Q%20primary%0A%20%20%20%20class%20R1%2CR2%2CR3%20secondary%0A%20%20%20%20class%20A1%2CA2%2CA3%20note%0A%20%20%20%20class%20V%2CO%20accent%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[s(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=n(`<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Question</span></span>
<span class="line"><span>  -&gt; reasoning steps</span></span>
<span class="line"><span>  -&gt; final answer</span></span></code></pre></div><p>이 방식은 특히 산술, 논리, multi-step reasoning task에서 성능을 높일 수 있다. 또한 debugging에 유리하다. 최종 답이 틀렸을 때 reasoning trace를 보면 어떤 context나 assumption이 잘못되었는지 찾기 쉽다.</p><p>단점은 token을 더 많이 생성하므로 latency와 cost가 증가한다는 점이다.</p><h3 id="self-consistency" tabindex="-1">Self-Consistency <a class="header-anchor" href="#self-consistency" aria-label="Permalink to &quot;Self-Consistency&quot;">​</a></h3><p>Self-consistency는 같은 prompt에 대해 여러 reasoning path를 sampling하고, 최종 답을 majority voting으로 고르는 방식이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sample response 1 -&gt; answer A</span></span>
<span class="line"><span>sample response 2 -&gt; answer B</span></span>
<span class="line"><span>sample response 3 -&gt; answer A</span></span>
<span class="line"><span>majority vote -&gt; answer A</span></span></code></pre></div><p>이를 사용하려면 최종 답을 추출할 수 있어야 한다. 보통 &quot;final answer를 마지막 줄에 쓰라&quot;는 constraint를 넣거나, regex 또는 별도 LLM으로 answer를 parse한다.</p><p>Self-consistency는 병렬 sampling이 가능하므로 latency는 병렬 generation 중 가장 느린 branch에 가까울 수 있다. 하지만 총 compute cost는 증가한다.</p><hr><h2 id="inference-efficiency" tabindex="-1">Inference Efficiency <a class="header-anchor" href="#inference-efficiency" aria-label="Permalink to &quot;Inference Efficiency&quot;">​</a></h2><p>강의 후반부는 inference optimization을 두 범주로 나눈다.</p><table tabindex="0"><thead><tr><th>Category</th><th>Meaning</th><th>Examples</th></tr></thead><tbody><tr><td>Exact</td><td>같은 결과를 더 효율적으로 계산</td><td>KV cache, PagedAttention, equation reformulation</td></tr><tr><td>Approximate</td><td>약간의 근사로 더 빠르게 생성</td><td>architecture variation, compact representation, speculative methods</td></tr></tbody></table><p>Autoregressive generation은 token을 하나씩 생성하기 때문에 naive하게 구현하면 이전 token의 key/value를 매번 다시 계산하게 된다. 이 중복을 제거하는 것이 KV cache의 핵심이다.</p><hr><h2 id="kv-cache" tabindex="-1">KV Cache <a class="header-anchor" href="#kv-cache" aria-label="Permalink to &quot;KV Cache&quot;">​</a></h2><p>Decoder-only generation에서 현재 token의 query는 새로 필요하지만, 과거 token의 key/value는 이미 계산한 값이다. 따라서 이를 저장해 두면 다음 step에서 재사용할 수 있다.</p><p><img src="`+h+`" alt="KV cache reuse during autoregressive decoding"></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step t:</span></span>
<span class="line"><span>  compute Q_t</span></span>
<span class="line"><span>  reuse K_1 ... K_t from cache</span></span>
<span class="line"><span>  reuse V_1 ... V_t from cache</span></span></code></pre></div><p>KV cache는 decoding 속도를 크게 개선하지만 memory를 많이 사용한다. Cache 크기는 대략 다음 항에 비례한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>batch_size x sequence_length x layers x kv_heads x head_dim</span></span></code></pre></div><p>Lecture 2에서 다룬 GQA/MQA는 KV head 수를 줄여 KV cache memory를 낮추는 방법이다.</p><p>Training에서는 보통 teacher forcing으로 전체 sequence를 한 번에 처리하기 때문에 autoregressive decoding의 KV cache 개념이 그대로 적용되지 않는다. KV cache는 주로 inference-time generation optimization이다.</p><hr><h2 id="pagedattention" tabindex="-1">PagedAttention <a class="header-anchor" href="#pagedattention" aria-label="Permalink to &quot;PagedAttention&quot;">​</a></h2><p>Naive KV cache allocation은 request마다 maximum context length만큼 memory를 미리 잡을 수 있다. 하지만 실제 generation은 EOS token에서 멈추므로, 대부분 request가 maximum length를 다 쓰지 않는다. 이는 memory waste와 fragmentation을 만든다.</p><p>PagedAttention은 KV cache를 고정 크기 block/page로 나누어 관리한다. Request 전체에 큰 contiguous memory를 예약하는 대신, 필요한 만큼 작은 block을 할당하고 mapping table로 token position과 cache block을 연결한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>naive allocation:</span></span>
<span class="line"><span>request -&gt; full max context memory block</span></span>
<span class="line"><span></span></span>
<span class="line"><span>paged allocation:</span></span>
<span class="line"><span>request -&gt; block 1 -&gt; block 2 -&gt; block 3 ...</span></span></code></pre></div><p>이 방식은 internal fragmentation과 external fragmentation을 줄인다. vLLM의 핵심 아이디어 중 하나로 알려져 있다.</p><hr><h2 id="multi-latent-attention" tabindex="-1">Multi-Latent Attention <a class="header-anchor" href="#multi-latent-attention" aria-label="Permalink to &quot;Multi-Latent Attention&quot;">​</a></h2><p>Multi-Latent Attention, MLA는 DeepSeek 계열에서 소개된 KV cache compact representation 기법으로 설명된다.</p><p>기본 multi-head attention에서는 head마다 key/value projection 결과를 저장해야 한다. 이는 layer와 sequence length가 커질수록 큰 memory pressure가 된다.</p><p>MLA의 아이디어는 key/value projection을 낮은 차원의 latent space로 factorization하는 것이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>token representation</span></span>
<span class="line"><span>  -&gt; compressed latent representation</span></span>
<span class="line"><span>  -&gt; decompressed key/value representation</span></span></code></pre></div><p>강의에서 강조한 점은 compression representation을 key와 value, 그리고 여러 head 사이에서 공유할 수 있다는 것이다. 이렇게 하면 token당 저장해야 할 cache representation 수가 줄어든다.</p><p>흥미로운 점은 이것이 단순한 hardware optimization만은 아니라는 것이다. 논문에서는 shared compact representation이 regularization처럼 작용해 성능 개선도 관찰됐다고 설명한다.</p><hr><h2 id="speculative-decoding" tabindex="-1">Speculative Decoding <a class="header-anchor" href="#speculative-decoding" aria-label="Permalink to &quot;Speculative Decoding&quot;">​</a></h2><p>Speculative decoding은 작은 draft model과 큰 target model을 함께 사용해 generation을 빠르게 하는 방법이다.</p><p>기본 흐름은 다음과 같다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 작은 draft model이 여러 token을 빠르게 제안한다.</span></span>
<span class="line"><span>2. 큰 target model이 이 draft token들을 한 번의 forward pass로 검증한다.</span></span>
<span class="line"><span>3. acceptance/rejection rule로 token을 채택하거나 거절한다.</span></span>
<span class="line"><span>4. 채택된 만큼 generation position을 앞으로 이동한다.</span></span></code></pre></div><p>작은 model은 빠르게 여러 token을 생성하고, 큰 model은 병렬적으로 그 token들의 probability를 계산한다. 모든 draft token이 accept되면 큰 model을 token마다 호출하는 것보다 더 빠르게 여러 token을 진행할 수 있다.</p><p>강의에서는 이 방식이 rejection sampling과 연결되며, 적절한 acceptance rule을 사용하면 target model의 distribution과 맞는 출력을 얻을 수 있다고 설명한다.</p><p>추론이 memory-bound인 경우, 큰 model을 여러 번 호출하는 대신 한 번에 여러 position의 probability를 계산하는 것이 효율적일 수 있다.</p><hr><h2 id="multi-token-prediction" tabindex="-1">Multi-Token Prediction <a class="header-anchor" href="#multi-token-prediction" aria-label="Permalink to &quot;Multi-Token Prediction&quot;">​</a></h2><p>Multi-token prediction은 speculative decoding과 비슷한 효율화 목표를 갖지만, draft model을 별도로 두지 않는다. 하나의 model 안에 여러 prediction head를 붙이고, training objective 자체를 next-token prediction이 아니라 multiple future token prediction으로 확장한다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>decoder representation</span></span>
<span class="line"><span>  -&gt; head 1 predicts token t+1</span></span>
<span class="line"><span>  -&gt; head 2 predicts token t+2</span></span>
<span class="line"><span>  -&gt; head 3 predicts token t+3</span></span></code></pre></div><p>Inference 시에는 여러 head가 draft token 역할을 하고, main head 또는 target path가 이를 검증하는 방식으로 사용할 수 있다. 강의에서는 draft model과 target model이 같은 architecture 안에 embedded된다는 점을 강조한다.</p><p>Speculative decoding처럼 정확한 target distribution 보장이 항상 같은 형태로 주어지는 것은 아니며, paper마다 greedy acceptance 등 변형된 방법을 사용한다.</p><hr><h2 id="practical-tips-and-notes" tabindex="-1">Practical Tips and Notes <a class="header-anchor" href="#practical-tips-and-notes" aria-label="Permalink to &quot;Practical Tips and Notes&quot;">​</a></h2><h3 id="llm-응답-품질은-model만으로-결정되지-않는다" tabindex="-1">LLM 응답 품질은 model만으로 결정되지 않는다 <a class="header-anchor" href="#llm-응답-품질은-model만으로-결정되지-않는다" aria-label="Permalink to &quot;LLM 응답 품질은 model만으로 결정되지 않는다&quot;">​</a></h3><p>같은 model이라도 decoding strategy, temperature, top-K/top-P, prompt structure, context selection에 따라 결과가 크게 달라진다. &quot;model이 틀렸다&quot;라고 판단하기 전에 prompt, sampling, context, output constraint를 분리해서 확인해야 한다.</p><h3 id="temperature는-창의성-knob이지만-품질-보장-knob은-아니다" tabindex="-1">Temperature는 창의성 knob이지만 품질 보장 knob은 아니다 <a class="header-anchor" href="#temperature는-창의성-knob이지만-품질-보장-knob은-아니다" aria-label="Permalink to &quot;Temperature는 창의성 knob이지만 품질 보장 knob은 아니다&quot;">​</a></h3><p>높은 temperature는 다양한 token을 더 자주 뽑게 하지만, 항상 더 좋은 답을 만든다는 뜻은 아니다. 코드 생성, 수학, factual QA처럼 deterministic correctness가 중요한 task는 낮은 temperature가 보통 유리하다. 브레인스토밍이나 문체 다양성이 중요한 task는 높은 temperature를 실험할 수 있다.</p><h3 id="long-context는-retrieval-품질을-대체하지-않는다" tabindex="-1">Long context는 retrieval 품질을 대체하지 않는다 <a class="header-anchor" href="#long-context는-retrieval-품질을-대체하지-않는다" aria-label="Permalink to &quot;Long context는 retrieval 품질을 대체하지 않는다&quot;">​</a></h3><p>Context length가 크더라도 distractor가 많으면 model이 필요한 정보를 놓칠 수 있다. 긴 문서를 통째로 넣는 것보다, retrieval과 reranking으로 필요한 chunk를 선별하고, prompt 안에서 evidence를 명확히 배치하는 것이 중요하다.</p><h3 id="kv-cache는-inference-memory의-핵심-병목이다" tabindex="-1">KV cache는 inference memory의 핵심 병목이다 <a class="header-anchor" href="#kv-cache는-inference-memory의-핵심-병목이다" aria-label="Permalink to &quot;KV cache는 inference memory의 핵심 병목이다&quot;">​</a></h3><p>Serving capacity를 계산할 때 parameter memory만 보면 부족하다. 긴 sequence, 큰 batch, 많은 layer, 많은 KV head는 KV cache memory를 빠르게 키운다. GQA/MQA, PagedAttention, context length limit, batching policy를 함께 봐야 한다.</p><h3 id="moe는-total-parameter와-active-parameter를-구분해서-봐야-한다" tabindex="-1">MoE는 total parameter와 active parameter를 구분해서 봐야 한다 <a class="header-anchor" href="#moe는-total-parameter와-active-parameter를-구분해서-봐야-한다" aria-label="Permalink to &quot;MoE는 total parameter와 active parameter를 구분해서 봐야 한다&quot;">​</a></h3><p>MoE model은 total parameter가 매우 커도 token당 active parameter는 상대적으로 작을 수 있다. 따라서 serving cost를 볼 때 total parameter만 보지 말고, active expert 수, routing policy, expert parallelism, load balancing을 확인해야 한다.</p><h3 id="structured-output은-prompt보다-decoder-constraint가-더-강하다" tabindex="-1">Structured output은 prompt보다 decoder constraint가 더 강하다 <a class="header-anchor" href="#structured-output은-prompt보다-decoder-constraint가-더-강하다" aria-label="Permalink to &quot;Structured output은 prompt보다 decoder constraint가 더 강하다&quot;">​</a></h3><p>JSON, SQL, grammar-constrained output이 필요하면 &quot;JSON으로 답해&quot;라는 prompt만으로는 부족할 수 있다. Guided decoding, schema validation, retry, parser feedback을 조합하는 것이 실무적으로 더 안정적이다.</p><h3 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>First Check</th></tr></thead><tbody><tr><td>응답이 매번 달라진다</td><td>temperature, sampling, top-K/top-P</td></tr><tr><td>JSON이 자주 깨진다</td><td>guided decoding, schema validation, retry strategy</td></tr><tr><td>긴 문서에서 답을 못 찾는다</td><td>retrieval quality, distractors, context ordering</td></tr><tr><td>serving memory가 부족하다</td><td>KV cache size, batch size, context length, GQA/MQA</td></tr><tr><td>MoE expert 일부만 쓰인다</td><td>routing collapse, load balancing loss, noisy gating</td></tr><tr><td>generation latency가 높다</td><td>KV cache, PagedAttention, speculative decoding</td></tr></tbody></table><hr><h2 id="lecture-summary" tabindex="-1">Lecture Summary <a class="header-anchor" href="#lecture-summary" aria-label="Permalink to &quot;Lecture Summary&quot;">​</a></h2><p>Lecture 3는 LLM을 decoder-only Transformer 기반의 next-token prediction system으로 정의한다. 현대 LLM은 parameter 수, training token 수, compute 규모가 크며, GPT, Llama, Gemma, DeepSeek, Mistral, Qwen 같은 대부분의 model이 decoder-only architecture를 사용한다.</p><p>강의는 먼저 MoE를 통해 model capacity와 active compute의 차이를 설명한다. Sparse MoE는 router가 token별 top-K expert를 선택하게 하여 total parameter를 크게 늘리면서도 forward pass의 FLOPs를 통제한다. 하지만 routing collapse가 생길 수 있어 load balancing loss와 noisy gating 같은 기법이 필요하다.</p><p>그 다음 응답 생성 방식을 다룬다. Greedy decoding은 deterministic하지만 다양성과 global sequence quality가 부족할 수 있다. Beam search는 여러 path를 유지해 더 높은 likelihood sequence를 찾으려 하지만 계산량이 크고 diversity가 낮다. 실제 LLM 응답 생성에서는 sampling, top-K, top-P, temperature가 중요하다. Temperature는 softmax distribution의 sharpness를 조절하며, 낮으면 deterministic에 가깝고 높으면 더 creative하지만 품질이 불안정해질 수 있다.</p><p>Prompting 영역에서는 context length와 context rot, prompt 구성요소, zero-shot/few-shot in-context learning, chain-of-thought, self-consistency를 다룬다. 긴 context는 강력하지만 distractor가 많으면 retrieval 성능이 떨어질 수 있다. 좋은 prompt는 context, instruction, input, constraint를 분리해 설계해야 한다.</p><p>마지막으로 inference efficiency를 다룬다. KV cache는 이전 token의 key/value를 재사용해 중복 계산을 줄이지만 memory 병목을 만든다. PagedAttention은 cache allocation fragmentation을 줄이고, multi-latent attention은 KV representation을 compact하게 만든다. Speculative decoding은 작은 draft model과 큰 target model을 함께 사용해 여러 token을 빠르게 진행하며, multi-token prediction은 draft behavior를 같은 model 안의 multiple heads로 통합하려는 접근이다.</p><hr><h2 id="key-terms" tabindex="-1">Key Terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>LLM</td><td>large decoder-only text generation language model</td></tr><tr><td>Language model</td><td>token sequence에 probability를 부여하는 model</td></tr><tr><td>Decoder-only</td><td>masked self-attention과 FFN 기반으로 next token을 생성하는 Transformer 계열</td></tr><tr><td>MoE</td><td>여러 expert network 중 일부를 선택해 사용하는 architecture</td></tr><tr><td>Router / Gate</td><td>input token을 어떤 expert로 보낼지 결정하는 network</td></tr><tr><td>Sparse MoE</td><td>top-K expert만 활성화하는 MoE</td></tr><tr><td>Routing collapse</td><td>router가 일부 expert만 계속 선택하는 현상</td></tr><tr><td>FLOPs</td><td>floating point operations, 계산량 단위</td></tr><tr><td>Greedy decoding</td><td>가장 높은 probability token을 항상 선택하는 decoding</td></tr><tr><td>Beam search</td><td>여러 candidate sequence path를 유지하는 decoding</td></tr><tr><td>Sampling</td><td>probability distribution에서 token을 확률적으로 뽑는 방식</td></tr><tr><td>Top-K</td><td>상위 K개 token만 남기고 sampling하는 방법</td></tr><tr><td>Top-P</td><td>누적 probability가 p가 될 때까지 token을 남기는 방법</td></tr><tr><td>Temperature</td><td>softmax distribution의 sharpness를 조절하는 hyperparameter</td></tr><tr><td>Guided decoding</td><td>grammar/schema상 invalid한 token을 막는 decoding</td></tr><tr><td>Context length</td><td>model이 한 번에 볼 수 있는 token 수</td></tr><tr><td>Context rot</td><td>긴 context에서 필요한 정보를 찾는 능력이 떨어지는 현상</td></tr><tr><td>In-context learning</td><td>weight update 없이 prompt 안의 pattern으로 task를 수행하는 방식</td></tr><tr><td>Chain of Thought</td><td>reasoning steps를 생성한 뒤 답을 내는 prompting</td></tr><tr><td>Self-consistency</td><td>여러 reasoning sample의 final answer를 voting하는 방법</td></tr><tr><td>KV cache</td><td>이전 token들의 key/value를 저장해 decoding에서 재사용하는 cache</td></tr><tr><td>PagedAttention</td><td>KV cache를 block/page 단위로 관리하는 방법</td></tr><tr><td>Multi-Latent Attention</td><td>KV representation을 compact latent로 factorize하는 attention 변형</td></tr><tr><td>Speculative decoding</td><td>작은 draft model과 큰 target model로 generation을 가속하는 방법</td></tr><tr><td>Multi-token prediction</td><td>여러 future token을 동시에 예측하도록 학습/추론하는 방법</td></tr></tbody></table><hr><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><ol><li>현대적 의미의 LLM은 왜 BERT와 구분되는가?</li><li>LLM이 large하다는 말은 어떤 세 가지 scale을 포함하는가?</li><li>Decoder-only LLM에서 cross-attention이 사라지는 이유는 무엇인가?</li><li>Sparse MoE는 total parameter와 active compute를 어떻게 분리하는가?</li><li>LLM에서 MoE expert가 주로 FFN 위치에 들어가는 이유는 무엇인가?</li><li>Routing collapse란 무엇이며 왜 문제가 되는가?</li><li>Greedy decoding이 locally optimal이지만 globally optimal이 아닐 수 있는 이유는 무엇인가?</li><li>Beam search가 짧은 sequence를 선호할 수 있는 이유는 무엇인가?</li><li>Top-K와 top-P sampling의 차이는 무엇인가?</li><li>Temperature가 낮을 때와 높을 때 probability distribution은 어떻게 변하는가?</li><li>Guided decoding은 structured output 문제를 어떻게 완화하는가?</li><li>Context length가 길어도 context rot이 문제가 되는 이유는 무엇인가?</li><li>Few-shot prompting이 항상 zero-shot보다 좋지 않을 수 있는 이유는 무엇인가?</li><li>Chain-of-thought가 debugging에 유리한 이유는 무엇인가?</li><li>KV cache는 어떤 중복 계산을 줄이는가?</li><li>PagedAttention이 naive KV cache allocation보다 유리한 이유는 무엇인가?</li><li>Speculative decoding에서 draft model과 target model의 역할은 무엇인가?</li><li>Multi-token prediction은 speculative decoding과 무엇이 다른가?</li></ol><hr><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><ol><li>BERT는 encoder-only representation model이며 text를 autoregressive하게 생성하지 않는다. 현대적 의미의 LLM은 대규모 decoder-only text-to-text generation model을 가리킨다.</li><li>Parameter 수, pre-training token 수, training/inference compute 규모다.</li><li>Decoder-only model에는 encoder가 없으므로 encoder output을 참조하는 cross-attention이 필요 없다.</li><li>전체 expert parameter는 크게 늘리지만, token당 top-K expert만 활성화해 forward pass의 active parameter와 FLOPs를 제한한다.</li><li>FFN은 <code>d_model -&gt; d_ff -&gt; d_model</code> 구조에서 <code>d_ff</code>가 커 parameter와 연산량이 많다. 따라서 expert로 분리했을 때 compute 절감 효과가 크다.</li><li>Router가 일부 expert만 계속 선택해 다른 expert가 거의 사용되지 않는 현상이다. Capacity가 낭비되고 일부 expert만 학습되어 model quality와 load balance가 나빠진다.</li><li>각 step에서 가장 높은 probability token을 고르는 것이 전체 sequence probability를 최대화한다는 보장은 없다. 초반에 약간 낮은 확률 token을 선택한 path가 이후 더 높은 확률을 이어갈 수 있다.</li><li>Sequence probability는 token probability의 곱이다. token 수가 늘어날수록 1보다 작은 값을 계속 곱하므로 긴 sequence score가 낮아진다. 그래서 length penalty가 필요하다.</li><li>Top-K는 상위 K개 token 수를 고정한다. Top-P는 cumulative probability mass가 p를 넘는 최소 token 집합을 사용한다.</li><li>낮은 temperature는 distribution을 sharp하게 만들어 top token에 집중한다. 높은 temperature는 distribution을 flatter하게 만들어 더 다양한 token이 선택될 수 있게 한다.</li><li>Grammar나 schema상 불가능한 next token을 decoding 중에 mask한다. 따라서 JSON이나 특정 grammar 같은 structured output을 더 안정적으로 생성할 수 있다.</li><li>Context가 길어질수록 distractor가 많아지고 필요한 정보가 희석될 수 있다. Model이 긴 context 안의 answer를 항상 안정적으로 retrieve하지 못한다.</li><li>Few-shot example이 task를 잘 보여주면 도움이 되지만, example이 좁거나 편향되면 model을 그 분포에 과하게 묶어 새로운 input에 대한 generalization을 방해할 수 있다.</li><li>Model이 어떤 intermediate assumption과 reasoning step을 거쳤는지 token으로 드러나기 때문이다. 틀린 답의 원인을 context, 날짜, 계산 단계 등에서 추적하기 쉽다.</li><li>이전 token들의 key/value projection을 다시 계산하지 않고 저장된 값을 재사용한다.</li><li>Request마다 maximum context length만큼 큰 memory block을 예약하지 않고, fixed-size block/page로 필요한 만큼 할당한다. 따라서 internal/external fragmentation이 줄고 serving capacity가 좋아진다.</li><li>Draft model은 여러 후보 token을 빠르게 제안한다. Target model은 그 token들을 검증하고 acceptance/rejection rule로 target distribution에 맞게 채택한다.</li><li>Speculative decoding은 별도 작은 draft model을 사용할 수 있다. Multi-token prediction은 같은 model 안에 여러 future-token prediction head를 두어 draft 역할을 model 내부에 통합한다.</li></ol>`,82))])}const A=d(m,[["render",u]]);export{C as __pageData,A as default};
